class Solution {
public:
    bool same(TreeNode* node, int want) {
        if (!node) return true;
        if (node->val != want) return false;
        return same(node->left, want) && same(node->right, want);
    }
    bool isUnivalTree(TreeNode* root) {
        return same(root, root->val);
    }
};
